const items = wb.getRange('Data!A7:A28').getValues().map(r=>r[0]);
const dates = wb.getRange('Data!G6:AX6').getValues()[0];
const qty = wb.getRange('Data!G7:AX28').getValues();
const out:any[][] = [];
items.forEach((it,i)=>dates.forEach((d,j)=>out.push([typeof it==='string' ? "'"+it : it, d, qty[i][j]])));
log(out.length);
wb.getRange('Transpose!A3:C970').setValues(out);
const src = wb.getRange('Data!A7:A28').getValues().map(r=>r[0]);
const a = wb.getRange('Transpose!A3:A970').getValues();
let bad=0; let k=0; for (let i=0;i<22;i++) for(let j=0;j<44;j++){ if(a[k][0]!==src[i]) bad++; k++; }
log('item mismatches',bad);
log(wb.getRange('Transpose!A3:C970').getCounts());

